import string

def encode_shift(s: str):
    """
    Returns encoded string by shifting every character by 5 in the alphabet.
    """
    shift = 5
    lowercase = {chr((ord(ch) + shift - ord("a")) % 26 + ord("a")): ch for ch in string.ascii_lowercase}
    return "".join(lowercase[ch] if ch in string.ascii_lowercase else ch for ch in s)

def decode_shift(s: str):
    """
    Takes as input string encoded with encode_shift function. Returns decoded string.
    """
    shift = 5
    inverse_shift = 26 - shift
    lowercase = {chr((ord(ch) - shift - ord("a")) % 26 + ord("a")): ch for ch in string.ascii_lowercase}
    return "".join(inverse_shift * ch if ch in string.ascii_lowercase else ch for ch in s)
```

