def histogram(test):
    """Given a string representing a space separated lowercase letters,
    return a dictionary of the letter with the most repetition and containing
    the corresponding count. If several letters have the same occurrence,
    return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test: return {}
    letters_count = {}
    max_count = 0

    for char in test:
        if char != ' ':
            letters_count[char] = letters_count.get(char, 0) + 1
            max_count = max(max_count, letters_count[char])

    result = {char: count for char, count in letters_count.items() if count == max_count}

    return result
