import math

def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci():
        a, b = 0, 1
        while True:
            if is_prime(b):
                yield b
            a, b = b, a + b

    return next(is_prime_n_th_fibonacci(n))

def is_prime_n_th_fibonacci(n: int):
    fib_gen = fibonacci()
    for _ in range(n - 1):
        next(fib_gen)
    return fib_gen
