def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) < 2:
        return True

    def increasing(nums):
        for i in range(1, len(nums)):
            if nums[i] < nums[i - 1]:
                return False
        return True

    def decreasing(nums):
        for i in range(1, len(nums)):
            if nums[i] > nums[i - 1]:
                return False
        return True

    return increasing(l) or decreasing(l)
