from itertools import product

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n

    def dfs(x, y, path):
        if len(path) == k:
            return path
        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in path:
                new_path = dfs(nx, ny, path + [(grid[nx][ny])])
                if min_path is None or new_path < min_path:
                    min_path = new_path
        return min_path

    min_path = dfs(0, 0, [])
    return min_path
