import sys

def check_planet(name):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if name not in planets:
        return False
    else:
        return planets.index(name)

def bf(planet1, planet2):
    if not (1 <= check_planet(planet1) <= 8 and 1 <= check_planet(planet2) <= 8):
        return ()

    start_index, end_index = sorted(check_planet(planet1), check_planet(planet2))

    if start_index == end_index:
        return (planets[start_index],)

    planets_between = []
    while start_index <= end_index:
        planets_between.append(planets[start_index])
        start_index += 1

    return tuple(planets_between)
