def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = ""
    for char in string:
        if char >= 'a' and char <= 'z':
            result += chr(ord(char) - 32)
        elif char >= 'A' and char <= 'Z':
            result += chr(ord(char) + 32)
        else:
            result += char
    return result
```

