def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers
    Example
    is_equal_to_sum_even(4) == False
    is_equal_to_sum_even(6) == False
    is_equal_to_sum_even(8) == True
    """
    if n < 8:
        return False
    for i in range(2, n//2 + 1, 2):
        remaining_sum = n - i
        if remaining_sum % 2 == 0 and remaining_sum >= 4:
            for j in range(2, remaining_sum//2 + 1, 2):
                remaining_sum_after_j = remaining_sum - j
                if remaining_sum_after_j % 2 == 0 and remaining_sum_after_j >= 4:
                    for k in range(2, remaining_sum_after_j//2 + 1, 2):
                        l = remaining_sum_after_j - k
                        if l % 2 == 0 and l > 0:
                            return True
    return False

