def encode(message):
    """
    This function takes a message and encodes it by swapping case
    of all letters and replacing vowels with the letter that appears
    two places ahead in the alphabet.

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'x',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'X'
    }
    encoded_message = []

    for char in message:
        if char.isalpha():
            if char in vowel_map:
                encoded_message.append(vowel_map[char])
            else:
                encoded_char = char.swapcase()
                if encoded_char in vowel_map:
                    encoded_message.append(vowel_map[encoded_char])
                else:
                    encoded_message.append(encoded_char)
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)

