import string

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiou'
    shifted_vowels = {vowels[i]: string.ascii_uppercase[i+2] if i < 4 else string.ascii_lowercase[i+2] for i, vow in enumerate(vowels)}

    def process_char(char):
        if char in shifted_vowels:
            return shifted_vowels[char]
        elif char.isupper():
            return char.lower()
        elif char.islower():
            return char.upper()
        else:
            return char

    encoded_message = ''.join(process_char(char) for char in message)
    return encoded_message
