import sys
from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    rows = [sys.maxsize] * n
    cols = [sys.maxsize] * n
    dp = [[[sys.maxsize] * (k + 1) for _ in range(n)] for _ in range(n)]
    dp[0][0][1] = grid[0][0]

    for length in range(1, k + 1):
        for i in range(n):
            for j in range(n):
                if length == 1:
                    dp[i][j][length] = grid[i][j]
                else:
                    dp[i][j][length] = min(dp[i][j][length], dp[rows[i]][cols[j]][length - 1])
                    if i > 0:
                        dp[i][j][length] = min(dp[i][j][length], dp[i - 1][j][length - 1])
                    if j > 0:
                        dp[i][j][length] = min(dp[i][j][length], dp[i][j - 1][length - 1])

    path = []
    i, j = n - 1, n - 1
    for length in range(k, 0, -1):
        path.append(dp[i][j][length])
        if dp[i][j][length] == dp[rows[i]][cols[j]][length - 1]:
            rows[i] = i
            cols[j] = j
            if i > 0:
                i -= 1
            else:
                j -= 1
        elif dp[i][j][length] == dp[i - 1][j][length - 1]:
            i -= 1
        else:
            j -= 1

    return path[::-1]
