    start2, end2 = interval2

    # Calculate the intersection
    start = max(start1, start2)
    end = min(end1, end2)

    # Check if intervals intersect
    if start > end:
        return "NO"

    # Calculate length of intersection
    length = end - start

    # Check if the length is a prime number
    if is_prime(length):
        return "YES"
    else:
        return "NO"

