import string

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 
    """
    encoding_dict = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'x', 'w': 'z',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'X', 'W': 'Z'
    }
    result = []
    for char in message:
        if char.isalpha():
            if char.islower():
                new_char = encoding_dict[char.upper()].lower()
            elif char.isupper():
                new_char = encoding_dict[char].lower()
            else:
                new_char = char
        else:
            new_char = char

        result.append(new_char)

    return ''.join(result)

# Examples provided in the docstring:
