import sys
from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    inf = sys.maxsize

    # Initialize the DP table
    dp = [[[inf] * (k + 1) for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            dp[i][j][0] = [grid[i][j]]

    # Fill the DP table
    for len_path in range(1, k + 1):
        for i in range(n):
            for j in range(n):
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < n:
                        for path in dp[i][j][len_path - 1]:
                            dp[ni][nj][len_path] = (
                                path + [grid[ni][nj]]
                                if len(path) < len(dp[ni][nj][len_path]) or path[-1] < grid[ni][nj]
                                else dp[ni][nj][len_path]
                            )

    # Find the minimum path
    min_path = inf
    for i in range(n):
        for j in range(n):
            for path in dp[i][j][k]:
                if len(path) < min_path:
                    min_path = len(path)
                    result = path
                elif len(path) == min_path and path < result:
                    result = path

    return result
