    def to_float_or_int(value):
        try:
            return float(value)
        except ValueError:
            # Check if the string represents an integer
            if re.match(r'^-?\d+$', value):
                return int(value)
            return value

    a, b = to_float_or_int(a), to_float_or_int(b)
    if a == b:
        return None
    elif isinstance(a, str) and isinstance(b, str):
        # Compare strings considering . or , as decimal separator
        return max(a, b, key=lambda x: x.replace(',', '.'))
    else:
        return max(a, b)
