from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    def is_balanced(group: str) -> bool:
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return not stack

    def get_groups(paren_string: str) -> List[str]:
        groups = []
        start = 0
        while start < len(paren_string):
            if paren_string[start] == ' ':
                start += 1
                continue
            end = start
            while end < len(paren_string) and paren_string[end] != ' ':
                end += 1
            group = paren_string[start:end]
            if is_balanced(group):
                groups.append(group)
            start = end
        return groups

    return get_groups(paren_string)
