from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    def is_balanced(group: str) -> bool:
        """ Helper function to check if a group of parentheses is balanced."""
        count = 0
        for char in group:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    def separate_group(group: str) -> List[str]:
        """ Helper function to recursively separate groups of parentheses."""
        result = []
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')' and stack:
                stack.pop()
                if not stack:
                    result.append(group[:len(group) - (len(group) - len(result[-1]))])
        return result

    groups = []
    start = 0
    while start < len(paren_string):
        if paren_string[start] == '(':
            end = start + 1
            while end < len(paren_string) and paren_string[end] != ')':
                end += 1
            groups.append(paren_string[start:end])
            start = end
        else:
            start += 1

    # Separate each group using the helper function
    return [separate_group(group) for group in groups]
