def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    # Split the test string into a list of letters
    letters = test.split(' ')
    # If there's only one input (test space), consider it as single letter 't'
    if len(letters) == 1:
        letters = letters[0]

    # Initialize a counter to keep track of each letter's occurrence
    counter = {}
    most_common_letters = {}

    # Iterate over the letters and update counter
    for letter in letters:
        if letter in counter:
            counter[letter] += 1
        else:
            counter[letter] = 1

    # Find all letters that have maximum frequency
    max_occurrence = max(counter.values())
    for letter, occurrence in counter.items():
        if occurrence == max_occurrence:
            most_common_letters[letter] = occurrence

    return most_common_letters
