def specialFilter(nums):
    def first_last_digits(num):
        """Helper function to check if first and last digits are odd."""
        str_num = str(abs(num))
        first_digit = int(str_num[0])
        last_digit = int(str_num[-1])
        return first_digit % 2, last_digit % 2

    def count_special(nums):
        """Helper function to count nums greater than 10 and meet filter condition."""
        count = 0
        for num in nums:
            if 10 < num < 100:
                if first_last_digits(num) == (1, 1):
                    count += 1
            elif first_last_digits(num) == (1, 1):
                if 10 < num < 100 or num > 100:
