import itertools
import math

def minPath(grid, k):
    N = len(grid)
    for i, row in enumerate(grid):
        for j, value in enumerate(row):
            grid[i][j] -= i + j + 1

    memo = {}

    def dfs(r, c, length):
        if (r, c, length) in memo:
            return memo[(r, c, length)]
        if length == 0:
            return {tuple(grid[r][c]: grid[r][c]]}
        if length < 0:
            return set()
        choices = []
        for dr, dc in (0, 1), (1, 0), (0, -1), (-1, 0):
            nr = dr + r
            nc = dc + c
            if 0 <= nr < N and 0 <= nc < N:
                choices.append((mob, length-1)for mob in dfs(nr, nc, length-1))
        return set(itertools.chain(*choices)) if choices else {tuple(grid[r][c] : grid[r][c]]}

    result = min(dfs(x, y, k) for y in range(N) for x in range(N))
    vals = list(result)
    vals.sort()
    return list(vals[0: k])
