def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def is_fib(num):
        a, b = 0, 1
        while b < num:
            a, b = b, a + b
        return b == num

    def find_nth_prime_fib(n):
        count = 0
        fib_num = 1
        while True:
            if is_prime(fib_num):
                count += 1
                if count == n:
                    return fib_num
            a, b = b, a + b
            if b > 1000000:  # Assuming we limit the search to a reasonable upper bound for performance
                raise ValueError("Fibonacci number exceeds the upper limit for prime check")

    return find_nth_prime_fib(n)
