def change_base(x: int, base: int) -> str:
    """Change numerical base of input number x to base.
    return string representation after the conversion.
    base numbers are less than 10.
    >>> change_base(8, 3)
    '22'
    >>> change_base(8, 2)
    '1000'
    >>> change_base(7, 2)
    '111'
    """
    def base_conv(num, conv_to):
        if num < conv_to:
            return str(num)
        else:
            return base_conv(num // conv_to, conv_to) + str(num % conv_to)

    return base_conv(x, base)
