def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    INF = sys.maxsize
    dp = [[[INF] * (k + 1) for _ in range(n)] for _ in range(n)]

    # Initialize starting point values
    for i in range(n):
        for j in range(n):
            dp[i][j][0] = grid[i][j]

    # Fill the dp array
    for length in range(1, k + 1):
        for i in range(n):
            for j in range(n):
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    x, y = i + dx, j + dy
                    if 0 <= x < n and 0 <= y < n:
                        dp[i][j][length] = min(dp[i][j][length], dp[x][y][length - 1])

    # Find the path with minimum value
    min_val = INF
    min_path = []
    for i in range(n):
        for j in range(n):
            if dp[i][j][k] < min_val:
                min_val = dp[i][j][k]
                min_path = [(i, j)]

    # Construct the final path from the minimum path
    for length in range(1, k):
        min_path.append(min_path[0])
        min_path[0] = (-1, -1)

    return [grid[i][j] for i, j in min_path]

