def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def is_fib(n):
        a, b = 0, 1
        while n > b:
            a, b = b, a + b
        return n == b

    def nth_prime_fib(n):
        count = 0
        fib = 0
        i = 0
        while True:
            if is_fib(fib) and is_prime(fib):
                count += 1
            if count == n:
                return fib
            if is_fib(fib):
                i += 1
                fib = a + b
            else:
                a, b = b, a + b

    return nth_prime_fib(n)
