def prime_fib(n: int):
    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    >>> prime_fib(1)
    2
    >>> prime_fib(2)
    3
    >>> prime_fib(3)
    5
    >>> prime_fib(4)
    13
    >>> prime_fib(5)
    89
    """

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def is_fib_and_prime(num):
        # Check if num is a Fibonacci number using matrix exponentiation
        def is_upper_fib(n):
            a = [1]
            for _ in range(n - 1):
                a.append(a[-1] + a[-2])
            if a and a[-1] == n:
                return True
            return False

        # Using the Lucas-Lehmer-Riesel test for prime checking
        def check_prime(n):
            return is_prime(n) and is_upper_fib(n)

        return check_prime(num)

    found_fib_and_prime = []
    a, b = 0, 1
    while n > 0:
        if is_fib_and_prime(b):
            found_fib_and_prime.append(b)
            n -= 1
        a, b = b, a + b
    return found_fib_and_prime[-1]
