import math

def is_prime(n):
    """Check if a number is a prime number.
    Return True if n is a prime, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def intersection(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2
    # Check if intervals don't intersect
    if start1 > end2 or start2 > end1:
        return "NO"
    # Merge the intervals
    start = max(start1, start2)
    end = min(end1, end2)
    length = end - start + 1
    # Check if the length of intersection is a prime number
    if is_prime(length):
        return "YES"
    return "NO"
