import re

def valid_date(date):
    """Checks if the date string is valid according to the specified rules."""

    # Check date format
    pattern = "^([1-9]|0[1-9]|1[0-2])-([1-9]|0[1-9]|[12][0-9]||30|31)-([0-9]{4})$"
    if not re.match(pattern, date):
        return False

    # Extract month, day, year
    month, day, year = map(int, date.split('-'))

    # Check month range
    if not 1 <= month <= 12:
        return False

    # Get number of days in month, except February
    if month in [4, 6, 9, 11]:
        max_days = 30
    elif month == 2 and is_binary_leap_year(year):
        max_days = 29
    else:
        max_days = 31

    # Check day range
    if not 1 <= day <= max_days:
        return False

    return True

def is_binary_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
