    Example
    is_equal_to_sum_even(4) == False
    is_equal_to_sum_even(6) == False
    is_equal_to_sum_even(8) == True
    """
    if n < 8:
        return False
    for i in range(2, n, 2):
        if n - i in range(2, n, 2):
            for j in range(2, n - i, 2):
                if n - i - j in range(2, n, 2):
                    k = n - i - j
                    if k > j and k % 2 == 0:
                        return True
    return False

# Example checks
