from typing import List


def remove_duplicates(numbers: List[int]) -> List[int]:
    """ From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> remove_duplicates([1, 2, 3, 2, 4])
    [1, 3, 4]
    """
    # Create a dictionary to count occurrences of each element
    count = {}
    # Iterate through numbers and populate count
    for num in numbers:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Filter out elements that occur more than once, preserving order
    result = []
    for num in numbers:
        if count[num] == 1:
            result.append(num)
        else:
            count[num] -= 1  # Ensure it's removed on the next iteration

    return result
```

