def sum_squares(lst):
    """Function that processes a list of integers based on their index multiples."""
    modified_list = []
    for i, x in enumerate(lst):
        if (i % 3 == 0):
            modified_list.append(x ** 2)
        elif (i % 4 == 0 and i % 3 != 0):
            modified_list.append(x ** 3)
    return sum(modified_list)
