import re
from datetime import datetime

def valid_date(date):
    if not date or not re.match(r'\d{2}-\d{2}-\d{4}', date):
        return False

    month, day, year = map(int, date.split('-'))

    # Months 1,3,5,7,8,10,12 have 31 days
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 1 <= day <= 31
    # Months 4,6,9,11 have 30 days
    elif month in (4, 6, 9, 11):
        return 1 <= day <= 30
    # February has 29 days
    else:
        return 1 <= day <= 29

    # Ensure the date is in the format mm-dd-yyyy
    return datetime(year, month, day).date() == datetime.strptime(date, '%m-%d-%Y')
