from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")
    if not paren_string:
        return []

    def is_valid_group(group: str) -> bool:
        """Check if a group of parentheses is valid."""
        count = 0
        for char in group:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    def separate_groups(group: str) -> List[str]:
        """Separate a group of parentheses into valid groups."""
        stack = []
        result = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')' and stack:
                result.append("".join(stack))
                stack = []
        if stack:
            result.append("".join(stack))
        return result

    # Main logic to separate groups
    groups = []
    start = 0
    while start < len(paren_string):
        if paren_string[start] == '(':
            end = start
            while end < len(paren_string) and paren_string[end] != ')':
                end += 1
            if end < len(paren_string) and paren_string[end] == ')':
                groups.append(paren_string[start:end + 1])
                start = end + 1
            else:
                start += 1
        else:
            start += 1

    # Ensure we separate complete groups
    return [group for group in groups if is_valid_group(group) and group != ""]
