def encrypt(s):
    """Create a function encrypt that takes a string as an argument and
    returns a string encrypted with the alphabet being rotated. 
    The alphabet should be rotated in a manner such that the letters 
    shift down by two multiplied to two places.
    For example:
    encrypt('hi') returns 'lm'
    encrypt('asdfghjkl') returns 'ewhjklnop'
    encrypt('gf') returns 'kj'
    encrypt('et') returns 'ix'
    """
    alphabet_lower = 'abcdefghijklmnopqrstuvwxyz'
    alphabet_upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    rotated_lower = alphabet_lower[2*len(alphabet_lower):] + alphabet_lower[:2*len(alphabet_lower)]
    rotated_upper = alphabet_upper[2*len(alphabet_upper):] + alphabet_upper[:2*len(alphabet_upper)]

    def rotate_char(c, rotate_fn):
        return rotate_fn[(alphabet_lower.index(c) + 2) % 26]

    def encrypt_char(c):
        if c.islower():
            return rotate_char(c, rotated_lower)
        else:
            return rotate_char(c, rotated_upper)

    return ''.join(encrypt_char(c) for c in s)
