import sys
from numpy import zeros

def minPath(grid, k):
    n = len(grid)
    dp = zeros((n, n, k + 1), dtype=int)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]  # right, down, up, left

    # Initialize the first row and column
    for i in range(1, k + 1):
        dp[0][i % n][i] = grid[0][i % n - 1]
        dp[i % n][0][i] = grid[i % n - 1][0]

    # Fill the dp table
    for i in range(1, n):
        for j in range(1, n):
            for t in range(1, k + 1):
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < n:
                        dp[i][j][t] = min(dp[i][j][t], dp[ni][nj][t - 1])
                dp[i][j][k] = min(dp[i][j][k], dp[i][j][k - 1])

    # Find the path with minimum value and reconstruct the path
    path = []
    for t in range(k, 0, -1):
        path.append(dp[0][0][t])
        for i in range(1, n):
            for j in range(1, n):
                dp[i][j][t - 1] += grid[i][j]

    return path[::-1]
