def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    def count(n, start=False, end=False):
        if n == 0:
            return 1
        count = 0
        if start:
            # For numbers starting with 1, the first digit is fixed as 1 and the rest can be anything.
            count += count(n - 1, True, False)
        if end:
            # For numbers ending with 1, the last digit must be 1 and the first n-1 digits can be anything.
            count += count(n - 1, True, True)
        if not start and not end:
            # For numbers that start and end with something else, we have n-1 positions to fill.
            count += 2 * count(n - 1, False, False)  # two choices for the first digit and then standard recursion.
        return count

    # Special case for n = 1
    if n == 1:
        return 1

    return count(n) - count(n, True, True)
