from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    def is_balanced(group: str) -> bool:
        count = 0
        for char in group:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count < 0:
                return False
        return count == 0

    def separate_group(group: str) -> List[str]:
        if is_balanced(group):
            return [group]
        result = []
        start = 0
        for i, char in enumerate(group):
            if char == '(':
                if is_balanced(group[start:i]):
                    result.append(group[start:i])
                start = i + 1
        if start < len(group):
            result.append(group[start:])
        return result

    groups = []
    start = 0
    for i, char in enumerate(paren_string):
        if char == ' ':
            continue
        if char == ')' and is_balanced(paren_string[start:i+1]):
            groups.append(paren_string[start:i+1])
            start = i + 1
    if start < len(paren_string):
        groups.append(paren_string[start:])
    return [separate_group(group) for group in groups]
