def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [2, 3]
    for num in range(5, a, 2):
        if is_prime(num) and num not in primes:
            primes.append(num)
            if len(primes) == 3:
                break

    return len(primes) == 3 and a == primes[0] * primes[1] * primes[2]

# Example usage
print(is_multiply_prime(30))  # Output: True
