def encode(message):
    """
    This function encodes a given message as described in the problem:
    swaps case of letters and modifies vowels based on the criteria.

    Parameters:
    - message: string to encode.

    Returns:
    - A string representing the encoded message.

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """

    def swap_case(char):
        if char >= 'a' and char <= 'z':
            return chr(ord(char) - 32)
        elif char >= 'A' and char <= 'Z':
            return chr(ord(char) + 32)
        return char

    def transform_vowel(char):
        vowels_transform_table = {  'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'x', 'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'X' }
        return vowels_transform_table.get(char, char)

    encoded_message = []

    for char in message:
        if 'a' <= char <= 'z':
            encoded_message.append(transform_vowel(char))
        elif 'A' <= char <= 'Z':
            encoded_message.append(transform_vowel(char))
        elif char.isalpha():
            encoded_message.append(swap_case(char))
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)

