from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.

    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]
    """
    def depth(parser):
        depth_stack = []
        max_depth = 0
        while parser:
            token = parser.pop(0)
            if token == '(':
                if depth_stack:
                    depth_stack.append(depth_stack[-1] + 1)
                else:
                    depth_stack.append(1)
            elif token == ')':
                max_depth = max(max_depth, depth_stack.pop())
            elif token.isdigit():
                parser_before = parser[:]
                for _ in range(int(token)):
                    parser.pop(0)
                parser.extend(parser_before)
        return max_depth

    result = []
    for group in paren_string.split(' '):
        parser = [c for c in group if c.isalpha()]
        result.append(depth([c for c in parser if c.isalpha()]))
    return result
