    letters = test.split()
    letter_counts = {}
    max_count = 0

    for letter in letters:
        if letter in letter_counts:
            letter_counts[letter] += 1
        else:
            letter_counts[letter] = 1

        if letter_counts[letter] > max_count:
            max_count = letter_counts[letter]

    # Filter the dictionary to include only those with the max_count
    result = {
        letter: count
        for letter, count in letter_counts.items()
        if count == max_count
    }

    return result
```

```python
def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    letter_count = {}
    max_count = 0
    result = []

    for letter in test.split():
        count = test.count(letter)
        letter_count[letter] = count
        if count == max_count:
            result.append(letter)
        elif count > max_count:
            result = [letter]
            max_count = count

    return {letter: count for letter, count in letter_count.items() if letter in result}
```

