    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    def helper(sub_str):
        if not sub_str:
            return []
        balance = 0
        start = -1
        for i, char in enumerate(sub_str):
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance == 0:
                return [sub_str[:i + 1]] + helper(sub_str[i + 1:])
        return [sub_str]

    return helper(paren_string.replace(' ', ''))
