import functools

def find_max(words):
    def unique_chars(word):
        return functools.reduce(lambda acc, char: acc | set(char), word, 0)

    if not words:
        return ""

    heapq.heapify(words)

    while len(words) > 1:
        word = heapq.heappop(words)
        if len(words) > 0:
            next_word = heapq.heappop(words)
            if unique_chars(next_word) > unique_chars(word):
                heapq.heappush(words, word)
            else:
                heapq.heappush(words, next_word)
        else:
            heapq.heappush(words, word)

    return heapq.heappop(words) if words else ""
