import re

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    # Helper function to convert string to number if necessary
    def convert_to_num(num):
        try:
            # Check if the number contains a comma
            num = num.replace(',', '.')
            return float(num)
        except ValueError:
            # Convert the string to an appropriate number if it's an integer
            return int(num)

    val_a = convert_to_num(a)
    val_b = convert_to_num(b)

    if val_a == val_b:
        return None
    elif isinstance(val_a, float) and isinstance(val_b, float):
        return val_b if val_b > val_a else val_a
    elif isinstance(val_a, str) or isinstance(val_b, str):
        return val_b if str(val_b) > str(val_a) else val_a
    else:
        return val_b if val_b > val_a else val_a
