from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    """ Input to this function is a string containing multiple groups of nested parentheses. Your goal is to
    separate those group into separate strings and return the list of those.
    Separate groups are balanced (each open brace is properly closed) and not nested within each other
    Ignore any spaces in the input string.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    def is_balanced(s: str) -> bool:
        """Check if the parentheses in the string are balanced."""
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    def find_group_start(s: str) -> int:
        """Find the starting index of a group of parentheses."""
        open_braces = 0
        for i, char in enumerate(s):
            if char == '(':
                open_braces += 1
            elif char == ')' and open_braces > 0:
                open_braces -= 1
            if open_braces == 0:
                return i

    def parse_group(s: str) -> str:
        """Parse a single group from the string."""
        start = find_group_start(s)
        group = s[:start]
        remaining = s[start + 1:]
        return group, parse_group(remaining) if remaining else []

    result = parse_group(paren_string.replace(' ', ''))
    return result
